export const panoramaViewerHtmlString = "<!doctype html>\n<html>\n    <head>\n        <meta charset=\"utf-8\" />\n        <meta\n            name=\"viewport\"\n            content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no\"\n        />\n        <title>360° Virtual Walkthrough</title>\n        <style>\n            * {\n                box-sizing: border-box;\n                margin: 0;\n                padding: 0;\n            }\n            body {\n                overflow: hidden;\n                background: #09090b;\n                font-family: -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, Helvetica, Arial, sans-serif;\n                user-select: none;\n                -webkit-user-select: none;\n            }\n            #canvas {\n                width: 100vw;\n                height: 100vh;\n                display: block;\n                cursor: grab;\n            }\n            #canvas:active {\n                cursor: grabbing;\n            }\n            #canvas.pointer-cursor {\n                cursor: pointer;\n            }\n\n            /* Loading Overlay */\n            #loading {\n                position: absolute;\n                top: 50%;\n                left: 50%;\n                transform: translate(-50%, -50%);\n                color: #ffffff;\n                font-size: 13px;\n                font-weight: 600;\n                letter-spacing: 0.3px;\n                background: rgba(15, 17, 23, 0.88);\n                padding: 12px 22px;\n                border-radius: 24px;\n                pointer-events: none;\n                z-index: 30;\n                box-shadow: 0 10px 30px rgba(0, 0, 0, 0.5);\n                display: flex;\n                align-items: center;\n                gap: 10px;\n                border: 1px solid rgba(255, 255, 255, 0.15);\n                backdrop-filter: blur(10px);\n            }\n            .spinner {\n                width: 18px;\n                height: 18px;\n                border: 2px solid rgba(255, 255, 255, 0.2);\n                border-top-color: #8A1538;\n                border-radius: 50%;\n                animation: spin 0.8s linear infinite;\n            }\n            @keyframes spin {\n                to { transform: rotate(360deg); }\n            }\n\n            /* Google Street View Top Header Card */\n            #top-header {\n                position: absolute;\n                top: 18px;\n                left: 20px;\n                display: flex;\n                flex-direction: column;\n                gap: 4px;\n                z-index: 20;\n                pointer-events: none;\n            }\n            .header-glass-card {\n                pointer-events: auto;\n                background: rgba(15, 17, 23, 0.82);\n                color: #ffffff;\n                padding: 10px 18px;\n                border-radius: 12px;\n                border: 1px solid rgba(255, 255, 255, 0.14);\n                box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);\n                backdrop-filter: blur(12px);\n                max-width: 380px;\n            }\n            .building-tag {\n                font-size: 10px;\n                font-weight: 800;\n                letter-spacing: 1.2px;\n                text-transform: uppercase;\n                color: rgba(255, 255, 255, 0.65);\n                display: flex;\n                align-items: center;\n                gap: 6px;\n                margin-bottom: 2px;\n            }\n            .building-tag .dot {\n                width: 6px;\n                height: 6px;\n                border-radius: 50%;\n                background: #8A1538;\n            }\n            .scene-title {\n                font-size: 15px;\n                font-weight: 700;\n                color: #ffffff;\n                letter-spacing: -0.2px;\n                overflow: hidden;\n                text-overflow: ellipsis;\n                white-space: nowrap;\n            }\n            .interaction-hint {\n                font-size: 11px;\n                color: rgba(255, 255, 255, 0.6);\n                margin-top: 3px;\n                display: flex;\n                align-items: center;\n                gap: 6px;\n            }\n\n            /* Google Street View Floating Toolbar (Right Side) */\n            #controls-toolbar {\n                position: absolute;\n                top: 72px;\n                right: 20px;\n                display: flex;\n                flex-direction: column;\n                gap: 6px;\n                z-index: 20;\n            }\n            .ctrl-box {\n                background: rgba(15, 17, 23, 0.85);\n                border-radius: 10px;\n                border: 1px solid rgba(255, 255, 255, 0.14);\n                box-shadow: 0 6px 20px rgba(0, 0, 0, 0.35);\n                backdrop-filter: blur(10px);\n                display: flex;\n                flex-direction: column;\n                overflow: hidden;\n            }\n            .ctrl-btn {\n                width: 38px;\n                height: 38px;\n                background: transparent;\n                color: #ffffff;\n                border: none;\n                display: flex;\n                align-items: center;\n                justify-content: center;\n                cursor: pointer;\n                font-size: 15px;\n                font-weight: 700;\n                transition: all 0.15s ease;\n            }\n            .ctrl-btn:hover {\n                background: rgba(255, 255, 255, 0.15);\n                color: #ffffff;\n            }\n            .ctrl-btn:active {\n                background: #8A1538;\n            }\n            .ctrl-divider {\n                width: 100%;\n                height: 1px;\n                background: rgba(255, 255, 255, 0.1);\n            }\n\n            /* Google Street View Compass Dial */\n            #compass-widget {\n                width: 38px;\n                height: 38px;\n                background: rgba(15, 17, 23, 0.85);\n                border-radius: 50%;\n                border: 1px solid rgba(255, 255, 255, 0.15);\n                box-shadow: 0 6px 18px rgba(0, 0, 0, 0.35);\n                backdrop-filter: blur(10px);\n                display: flex;\n                align-items: center;\n                justify-content: center;\n                cursor: pointer;\n                position: relative;\n                margin-bottom: 4px;\n                transition: transform 0.15s ease;\n            }\n            #compass-widget:hover {\n                transform: scale(1.08);\n                border-color: rgba(255, 255, 255, 0.3);\n            }\n            #compass-needle {\n                width: 22px;\n                height: 22px;\n                display: flex;\n                align-items: center;\n                justify-content: center;\n                transition: transform 0.05s linear;\n            }\n\n            /* Floating 3D Hover Tooltip */\n            #floating-labels {\n                position: absolute;\n                top: 0;\n                left: 0;\n                width: 100%;\n                height: 100%;\n                pointer-events: none;\n                z-index: 10;\n            }\n            .floating-label {\n                position: absolute;\n                background: rgba(15, 17, 23, 0.92);\n                color: #ffffff;\n                font-weight: 700;\n                padding: 6px 14px;\n                border-radius: 18px;\n                font-size: 12px;\n                pointer-events: none;\n                transform: translate(-50%, -100%);\n                opacity: 0;\n                white-space: nowrap;\n                box-shadow: 0 6px 20px rgba(0, 0, 0, 0.5);\n                transition: opacity 0.2s cubic-bezier(0.16, 1, 0.3, 1), transform 0.2s cubic-bezier(0.16, 1, 0.3, 1);\n                text-align: center;\n                border: 1px solid rgba(255, 255, 255, 0.8);\n                display: flex;\n                align-items: center;\n                gap: 6px;\n                backdrop-filter: blur(8px);\n            }\n            .floating-label .arrow-icon {\n                color: #ff476f;\n                font-size: 12px;\n            }\n            .floating-label::after {\n                content: '';\n                position: absolute;\n                top: 100%;\n                left: 50%;\n                margin-left: -5px;\n                border-width: 5px;\n                border-style: solid;\n                border-color: rgba(15, 17, 23, 0.92) transparent transparent transparent;\n            }\n\n            /* Google Street View Connected Rooms / Hotspots Dock */\n            #hotspots-dock {\n                position: absolute;\n                bottom: 56px;\n                left: 50%;\n                transform: translateX(-50%);\n                display: flex;\n                gap: 10px;\n                flex-wrap: wrap;\n                justify-content: center;\n                max-width: 88vw;\n                z-index: 20;\n                pointer-events: none;\n            }\n            .hotspot-chip {\n                pointer-events: auto;\n                background: rgba(15, 17, 23, 0.88);\n                color: #ffffff;\n                border: 1px solid rgba(255, 255, 255, 0.22);\n                padding: 8px 18px;\n                border-radius: 22px;\n                cursor: pointer;\n                font-size: 13px;\n                font-weight: 600;\n                display: flex;\n                align-items: center;\n                gap: 8px;\n                box-shadow: 0 6px 20px rgba(0, 0, 0, 0.45);\n                backdrop-filter: blur(10px);\n                transition: all 0.2s cubic-bezier(0.16, 1, 0.3, 1);\n            }\n            .hotspot-chip:hover {\n                background: #8A1538;\n                border-color: rgba(255, 255, 255, 0.6);\n                transform: translateY(-2px) scale(1.04);\n                box-shadow: 0 8px 24px rgba(138, 21, 56, 0.6);\n            }\n            .hotspot-chip .chip-arrow {\n                color: #ff476f;\n                font-size: 13px;\n                transition: transform 0.15s ease;\n            }\n            .hotspot-chip:hover .chip-arrow {\n                color: #ffffff;\n                transform: translateX(2px);\n            }\n\n            /* Google Street View Collapsible Bottom Filmstrip Drawer */\n            #bottom-dock {\n                position: absolute;\n                bottom: 16px;\n                left: 50%;\n                transform: translateX(-50%);\n                display: flex;\n                flex-direction: column;\n                align-items: center;\n                z-index: 20;\n                transition: all 0.3s cubic-bezier(0.16, 1, 0.3, 1);\n            }\n            #toggle-filmstrip-btn {\n                background: rgba(15, 17, 23, 0.85);\n                color: #ffffff;\n                border: 1px solid rgba(255, 255, 255, 0.16);\n                border-radius: 20px;\n                padding: 6px 14px;\n                font-size: 11px;\n                font-weight: 700;\n                letter-spacing: 0.3px;\n                cursor: pointer;\n                display: flex;\n                align-items: center;\n                gap: 6px;\n                box-shadow: 0 4px 16px rgba(0, 0, 0, 0.35);\n                backdrop-filter: blur(10px);\n                transition: all 0.15s ease;\n            }\n            #toggle-filmstrip-btn:hover {\n                background: #8A1538;\n                border-color: rgba(255, 255, 255, 0.3);\n            }\n            #filmstrip-container {\n                display: none;\n                margin-top: 10px;\n                background: rgba(12, 14, 20, 0.92);\n                border: 1px solid rgba(255, 255, 255, 0.14);\n                border-radius: 14px;\n                padding: 10px 14px;\n                box-shadow: 0 10px 32px rgba(0, 0, 0, 0.55);\n                backdrop-filter: blur(14px);\n                max-width: 90vw;\n                overflow-x: auto;\n                scrollbar-width: thin;\n                scrollbar-color: rgba(255, 255, 255, 0.3) transparent;\n            }\n            #filmstrip-container::-webkit-scrollbar {\n                height: 5px;\n            }\n            #filmstrip-container::-webkit-scrollbar-thumb {\n                background: rgba(255, 255, 255, 0.3);\n                border-radius: 4px;\n            }\n            #filmstrip-cards {\n                display: flex;\n                gap: 10px;\n                align-items: center;\n            }\n            .filmstrip-card {\n                width: 105px;\n                flex-shrink: 0;\n                cursor: pointer;\n                border-radius: 8px;\n                overflow: hidden;\n                border: 1.5px solid rgba(255, 255, 255, 0.15);\n                background: #18181b;\n                transition: all 0.18s ease;\n                display: flex;\n                flex-direction: column;\n            }\n            .filmstrip-card:hover {\n                border-color: #ffffff;\n                transform: translateY(-2px);\n            }\n            .filmstrip-card.active {\n                border-color: #8A1538;\n                box-shadow: 0 0 12px rgba(138, 21, 56, 0.7);\n            }\n            .filmstrip-card img {\n                width: 100%;\n                height: 54px;\n                object-fit: cover;\n                display: block;\n            }\n            .filmstrip-card-title {\n                padding: 4px 6px;\n                font-size: 10px;\n                font-weight: 600;\n                color: #ffffff;\n                overflow: hidden;\n                text-overflow: ellipsis;\n                white-space: nowrap;\n                text-align: center;\n                background: rgba(0, 0, 0, 0.6);\n            }\n\n            /* Cinematic Dolly Crossfade Transition Overlay */\n            #crossfade-overlay {\n                position: absolute;\n                top: 0;\n                left: 0;\n                width: 100%;\n                height: 100%;\n                background: #000000;\n                opacity: 0;\n                pointer-events: none;\n                transition: opacity 0.35s ease;\n                z-index: 25;\n            }\n        </style>\n    </head>\n    <body>\n        <!-- Google Street View Top Header Card -->\n        <div id=\"top-header\">\n            <div class=\"header-glass-card\">\n                <div class=\"building-tag\">\n                    <span class=\"dot\"></span>\n                    <span id=\"building-name-text\">ARQuest Campus Tour</span>\n                </div>\n                <div class=\"scene-title\" id=\"scene-title-text\">\n                    360° Panorama Walkthrough\n                </div>\n                <div class=\"interaction-hint\">\n                    <span>🖱️ Drag to look</span>\n                    <span>•</span>\n                    <span>👆 Click floor chevrons to walk</span>\n                </div>\n            </div>\n        </div>\n\n        <!-- Google Street View Controls Panel (Right Side) -->\n        <div id=\"controls-toolbar\">\n            <!-- Compass Needle Dial -->\n            <div id=\"compass-widget\" title=\"Face North (Click to Reorient)\">\n                <div id=\"compass-needle\">\n                    <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\">\n                        <polygon points=\"12,2 16,12 12,9 8,12\" fill=\"#e11d48\"/>\n                        <polygon points=\"12,22 16,12 12,9 8,12\" fill=\"#ffffff\" opacity=\"0.8\"/>\n                    </svg>\n                </div>\n            </div>\n\n            <!-- Zoom & View Tools -->\n            <div class=\"ctrl-box\">\n                <button class=\"ctrl-btn\" id=\"btn-zoom-in\" title=\"Zoom In (+)\">+</button>\n                <div class=\"ctrl-divider\"></div>\n                <button class=\"ctrl-btn\" id=\"btn-zoom-out\" title=\"Zoom Out (−)\">−</button>\n                <div class=\"ctrl-divider\"></div>\n                <button class=\"ctrl-btn\" id=\"btn-reset\" title=\"Reset to Entrance (Start Scene)\">🔄</button>\n                <div class=\"ctrl-divider\"></div>\n                <button class=\"ctrl-btn\" id=\"btn-fullscreen\" title=\"Toggle Fullscreen\">⛶</button>\n            </div>\n        </div>\n\n        <!-- Connected Rooms / Hotspots Navigation Chips -->\n        <div id=\"hotspots-dock\"></div>\n\n        <!-- Collapsible Bottom Filmstrip Drawer -->\n        <div id=\"bottom-dock\">\n            <button id=\"toggle-filmstrip-btn\" title=\"Show or hide scenes strip\">\n                <span>🖼️ Browse Scenes</span>\n                <span id=\"filmstrip-arrow\">▴</span>\n            </button>\n            <div id=\"filmstrip-container\">\n                <div id=\"filmstrip-cards\"></div>\n            </div>\n        </div>\n\n        <div id=\"loading\">\n            <div class=\"spinner\"></div>\n            <span id=\"loading-text\">Loading 360° Scene...</span>\n        </div>\n        <div id=\"crossfade-overlay\"></div>\n        <canvas id=\"canvas\"></canvas>\n        <div id=\"floating-labels\"></div>\n\n        <script type=\"importmap\">\n            {\n                \"imports\": {\n                    \"three\": \"https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js\"\n                }\n            }\n        </script>\n        <script type=\"module\">\n            import * as THREE from \"three\";\n\n            let scene, camera, renderer, sphereMesh, texture, animFrameId;\n            let lon = 0,\n                lat = 0,\n                isDragging = false;\n            let previousMousePosition = { x: 0, y: 0 };\n            let velocityLon = 0,\n                velocityLat = 0;\n            let mouseMovedDistance = 0;\n            let currentHotspots = [];\n            let allScenesList = [];\n            let currentSceneTitle = \"\";\n            let hotspotGroups = [];\n            let clickableHitboxes = [];\n            let hoveredHitbox = null;\n            let rippleMeshes = [];\n            let fov = 75;\n            let defaultFov = 75;\n            let minFov = 30;\n            let maxFov = 85;\n            let chevronTexture = null;\n            let isTransitioning = false;\n            let filmstripOpen = false;\n\n            // Generate authentic Google Street View Ground Chevron Texture\n            function createGoogleStreetViewChevronTexture() {\n                const canvas = document.createElement(\"canvas\");\n                canvas.width = 256;\n                canvas.height = 256;\n                const ctx = canvas.getContext(\"2d\");\n\n                ctx.clearRect(0, 0, 256, 256);\n\n                // 1. Soft Ambient Floor Shadow\n                const shadowGrad = ctx.createRadialGradient(128, 134, 40, 128, 134, 108);\n                shadowGrad.addColorStop(0, \"rgba(0, 0, 0, 0.35)\");\n                shadowGrad.addColorStop(0.8, \"rgba(0, 0, 0, 0.15)\");\n                shadowGrad.addColorStop(1, \"rgba(0, 0, 0, 0)\");\n                ctx.beginPath();\n                ctx.arc(128, 134, 108, 0, Math.PI * 2);\n                ctx.fillStyle = shadowGrad;\n                ctx.fill();\n\n                // 2. Google Street View Frosted Glass Disc Body\n                const discGrad = ctx.createRadialGradient(128, 128, 20, 128, 128, 96);\n                discGrad.addColorStop(0, \"rgba(255, 255, 255, 0.65)\");\n                discGrad.addColorStop(0.7, \"rgba(255, 255, 255, 0.45)\");\n                discGrad.addColorStop(1, \"rgba(255, 255, 255, 0.22)\");\n\n                ctx.beginPath();\n                ctx.arc(128, 128, 96, 0, Math.PI * 2);\n                ctx.fillStyle = discGrad;\n                ctx.fill();\n\n                // Disc rim\n                ctx.lineWidth = 3;\n                ctx.strokeStyle = \"rgba(255, 255, 255, 0.85)\";\n                ctx.stroke();\n\n                // 3. Crisp High-Contrast Forward Double Chevron Arrow\n                ctx.lineJoin = \"round\";\n                ctx.lineCap = \"round\";\n\n                // Function to draw chevron with shadow & stroke for 100% ground visibility\n                function drawChevron(yOffset) {\n                    ctx.beginPath();\n                    ctx.moveTo(128, yOffset);\n                    ctx.lineTo(176, yOffset + 48);\n                    ctx.lineTo(162, yOffset + 62);\n                    ctx.lineTo(128, yOffset + 28);\n                    ctx.lineTo(94, yOffset + 62);\n                    ctx.lineTo(80, yOffset + 48);\n                    ctx.closePath();\n\n                    // Dark outline for contrast on white tile floors\n                    ctx.lineWidth = 4;\n                    ctx.strokeStyle = \"rgba(0, 0, 0, 0.35)\";\n                    ctx.stroke();\n\n                    // Pure white fill\n                    ctx.fillStyle = \"#ffffff\";\n                    ctx.fill();\n                }\n\n                drawChevron(56);\n                drawChevron(112);\n\n                const tex = new THREE.CanvasTexture(canvas);\n                tex.colorSpace = THREE.SRGBColorSpace;\n                tex.needsUpdate = true;\n                return tex;\n            }\n\n            chevronTexture = createGoogleStreetViewChevronTexture();\n\n            let currentImageUrl = \"\";\n            let currentLoadRequestId = 0;\n\n            function createFallbackGridTexture(title) {\n                const canvas = document.createElement(\"canvas\");\n                canvas.width = 2048;\n                canvas.height = 1024;\n                const ctx = canvas.getContext(\"2d\");\n\n                // Deep modern dark gradient\n                const grad = ctx.createLinearGradient(0, 0, 0, 1024);\n                grad.addColorStop(0, \"#080c14\");\n                grad.addColorStop(0.48, \"#141c2c\");\n                grad.addColorStop(0.52, \"#101624\");\n                grad.addColorStop(1, \"#070a12\");\n                ctx.fillStyle = grad;\n                ctx.fillRect(0, 0, 2048, 1024);\n\n                // Horizon accent band\n                ctx.strokeStyle = \"rgba(138, 21, 56, 0.45)\";\n                ctx.lineWidth = 4;\n                ctx.beginPath();\n                ctx.moveTo(0, 512);\n                ctx.lineTo(2048, 512);\n                ctx.stroke();\n\n                // Spatial coordinate grid\n                ctx.strokeStyle = \"rgba(255, 255, 255, 0.07)\";\n                ctx.lineWidth = 1.5;\n                for (let x = 0; x <= 2048; x += 128) {\n                    ctx.beginPath();\n                    ctx.moveTo(x, 0);\n                    ctx.lineTo(x, 1024);\n                    ctx.stroke();\n                }\n                for (let y = 0; y <= 1024; y += 64) {\n                    ctx.beginPath();\n                    ctx.moveTo(0, y);\n                    ctx.lineTo(2048, y);\n                    ctx.stroke();\n                }\n\n                // Centered Room Title\n                ctx.fillStyle = \"#ffffff\";\n                ctx.font = \"bold 44px -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif\";\n                ctx.textAlign = \"center\";\n                ctx.fillText(title || \"360° Panorama Studio\", 1024, 460);\n\n                ctx.fillStyle = \"rgba(255, 255, 255, 0.65)\";\n                ctx.font = \"24px -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif\";\n                ctx.fillText(\"Interactive Walkthrough • Click chevrons or chips to navigate\", 1024, 550);\n\n                const tex = new THREE.CanvasTexture(canvas);\n                tex.colorSpace = THREE.SRGBColorSpace;\n                tex.needsUpdate = true;\n                return tex;\n            }\n\n            function cleanupHotspots() {\n                hotspotGroups.forEach((group) => {\n                    scene.remove(group);\n                    group.traverse((child) => {\n                        if (child.geometry) child.geometry.dispose();\n                        if (child.material) child.material.dispose();\n                    });\n                });\n                hotspotGroups = [];\n                clickableHitboxes = [];\n                hoveredHitbox = null;\n                const labels = document.getElementById(\"floating-labels\");\n                if (labels) labels.innerHTML = \"\";\n            }\n\n            function renderHotspotChips() {\n                const container = document.getElementById(\"hotspots-dock\");\n                if (!container) return;\n                container.innerHTML = \"\";\n                if (!currentHotspots || currentHotspots.length === 0) return;\n\n                currentHotspots.forEach((hotspot) => {\n                    const chip = document.createElement(\"button\");\n                    chip.className = \"hotspot-chip\";\n                    chip.innerHTML = `<span class=\"chip-arrow\">➔</span> <span>${hotspot.label || hotspot.target_scene_title || \"Next Room\"}</span>`;\n                    chip.onclick = (e) => {\n                        e.stopPropagation();\n                        triggerGoogleStreetViewStep(hotspot);\n                    };\n                    container.appendChild(chip);\n                });\n            }\n\n            function applyTextureToSphere(loadedTexture, isFallback = false) {\n                if (sphereMesh) {\n                    scene.remove(sphereMesh);\n                    sphereMesh.geometry.dispose();\n                    sphereMesh.material.dispose();\n                    sphereMesh = null;\n                    if (texture) {\n                        texture.dispose();\n                        texture = null;\n                    }\n                }\n                texture = loadedTexture;\n\n                const maxAnisotropy = renderer ? renderer.capabilities.getMaxAnisotropy() : 16;\n                texture.anisotropy = maxAnisotropy;\n                texture.minFilter = THREE.LinearFilter;\n                texture.magFilter = THREE.LinearFilter;\n                texture.generateMipmaps = false;\n                texture.colorSpace = THREE.SRGBColorSpace;\n\n                const imgWidth = texture.image ? (texture.image.width || 4000) : 4000;\n                const imgHeight = texture.image ? (texture.image.height || 2000) : 2000;\n                const aspectRatio = imgWidth / imgHeight;\n\n                let geometry;\n                if (aspectRatio >= 1.6 && aspectRatio <= 2.4) {\n                    geometry = new THREE.SphereGeometry(500, 64, 40);\n                    geometry.scale(-1, 1, 1);\n                } else {\n                    const radius = 500;\n                    const circumference = 2 * Math.PI * radius;\n                    const cylinderHeight = (imgHeight / imgWidth) * circumference;\n                    geometry = new THREE.CylinderGeometry(radius, radius, cylinderHeight, 64, 1, true);\n                    geometry.scale(-1, 1, 1);\n                }\n\n                const material = new THREE.MeshBasicMaterial({ map: texture });\n                sphereMesh = new THREE.Mesh(geometry, material);\n                scene.add(sphereMesh);\n\n                fov = defaultFov;\n                camera.fov = fov;\n                camera.updateProjectionMatrix();\n                lat = 0;\n                lon = 0;\n                velocityLon = 0;\n                velocityLat = 0;\n\n                const loadingEl = document.getElementById(\"loading\");\n                if (loadingEl) loadingEl.style.display = \"none\";\n\n                createGoogleStreetViewHotspots();\n                renderHotspotChips();\n                renderFilmstrip();\n\n                isTransitioning = false;\n                const crossfade = document.getElementById(\"crossfade-overlay\");\n                if (crossfade) crossfade.style.opacity = \"0\";\n\n                notifyParent({ type: isFallback ? \"fallback_loaded\" : \"loaded\" });\n                if (!renderer.info.render.frame) animate();\n            }\n\n            function init(imageUrl, hotspots, sceneTitle, buildingName, allScenes) {\n                currentHotspots = hotspots || [];\n                currentSceneTitle = sceneTitle || \"360° Scene\";\n                if (allScenes && Array.isArray(allScenes)) {\n                    allScenesList = allScenes;\n                }\n                renderFilmstrip();\n                renderHotspotChips();\n\n                if (sceneTitle) {\n                    const badge = document.getElementById(\"scene-title-text\");\n                    if (badge) badge.textContent = sceneTitle;\n                }\n                if (buildingName) {\n                    const bText = document.getElementById(\"building-name-text\");\n                    if (bText) bText.textContent = buildingName;\n                }\n\n                // If texture is already loaded for this same image URL, just rebuild hotspots without reloading image\n                if (sphereMesh && texture && currentImageUrl === imageUrl) {\n                    createGoogleStreetViewHotspots();\n                    renderHotspotChips();\n                    renderFilmstrip();\n                    isTransitioning = false;\n                    const loadingEl = document.getElementById(\"loading\");\n                    if (loadingEl) loadingEl.style.display = \"none\";\n                    const crossfade = document.getElementById(\"crossfade-overlay\");\n                    if (crossfade) crossfade.style.opacity = \"0\";\n                    return;\n                }\n\n                currentImageUrl = imageUrl;\n                cleanupHotspots();\n\n                if (!scene) {\n                    scene = new THREE.Scene();\n                    camera = new THREE.PerspectiveCamera(\n                        fov,\n                        window.innerWidth / window.innerHeight,\n                        0.1,\n                        1100,\n                    );\n                    camera.position.set(0, 0, 0.1);\n                    renderer = new THREE.WebGLRenderer({\n                        canvas: document.getElementById(\"canvas\"),\n                        antialias: true,\n                        powerPreference: \"high-performance\",\n                    });\n                    renderer.setSize(window.innerWidth, window.innerHeight);\n                    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));\n                    renderer.outputColorSpace = THREE.SRGBColorSpace;\n\n                    setupControls();\n                    setupToolbarEvents();\n                    window.addEventListener(\"resize\", () => {\n                        camera.aspect = window.innerWidth / window.innerHeight;\n                        camera.updateProjectionMatrix();\n                        renderer.setSize(window.innerWidth, window.innerHeight);\n                    });\n                }\n\n                const loadingEl = document.getElementById(\"loading\");\n                if (loadingEl) {\n                    loadingEl.style.display = \"flex\";\n                    document.getElementById(\"loading-text\").textContent = \"Loading 360° Scene...\";\n                }\n\n                const requestId = ++currentLoadRequestId;\n                const timeoutId = setTimeout(() => {\n                    if (requestId === currentLoadRequestId && !sphereMesh) {\n                        console.warn(\"Panorama load timeout reached. Applying fallback grid...\");\n                        applyTextureToSphere(createFallbackGridTexture(currentSceneTitle), true);\n                    }\n                }, 4000);\n\n                if (!imageUrl) {\n                    clearTimeout(timeoutId);\n                    applyTextureToSphere(createFallbackGridTexture(currentSceneTitle), true);\n                    return;\n                }\n\n                function loadPanoramaTexture(url, retryWithProxy = true) {\n                    const loader = new THREE.TextureLoader();\n                    loader.setCrossOrigin(\"anonymous\");\n                    loader.load(\n                        url,\n                        (loadedTexture) => {\n                            clearTimeout(timeoutId);\n                            if (requestId !== currentLoadRequestId) {\n                                loadedTexture.dispose();\n                                return;\n                            }\n                            applyTextureToSphere(loadedTexture, false);\n                        },\n                        undefined,\n                        (error) => {\n                            const isPrivate = url.includes(\"localhost\") || url.includes(\"127.0.0.1\") || url.includes(\"10.\") || url.includes(\"192.168.\");\n                            if (retryWithProxy && url.startsWith(\"http\") && !isPrivate && !url.includes(\"images.weserv.nl\")) {\n                                console.warn(\"Direct texture load failed. Retrying via CORS proxy fallback...\");\n                                const proxyUrl = `https://images.weserv.nl/?url=${encodeURIComponent(url)}&output=jpg&q=100&we`;\n                                loadPanoramaTexture(proxyUrl, false);\n                                return;\n                            }\n                            clearTimeout(timeoutId);\n                            console.warn(\"Texture load failed. Applying schematic grid fallback...\", error);\n                            if (requestId === currentLoadRequestId) {\n                                applyTextureToSphere(createFallbackGridTexture(currentSceneTitle), true);\n                            }\n                        },\n                    );\n                }\n\n                loadPanoramaTexture(imageUrl, true);\n            }\n\n            function setupToolbarEvents() {\n                // Compass click -> smoothly face North (lon = 0)\n                document.getElementById(\"compass-widget\").onclick = () => {\n                    const duration = 300;\n                    const startLon = lon;\n                    const startTime = performance.now();\n                    function animCompass(now) {\n                        const prog = Math.min((now - startTime) / duration, 1.0);\n                        const ease = prog * (2 - prog);\n                        lon = startLon * (1 - ease);\n                        if (prog < 1.0) requestAnimationFrame(animCompass);\n                    }\n                    requestAnimationFrame(animCompass);\n                };\n\n                // Zoom In\n                document.getElementById(\"btn-zoom-in\").onclick = () => {\n                    fov = Math.max(minFov, fov - 10);\n                    camera.fov = fov;\n                    camera.updateProjectionMatrix();\n                };\n\n                // Zoom Out\n                document.getElementById(\"btn-zoom-out\").onclick = () => {\n                    fov = Math.min(maxFov, fov + 10);\n                    camera.fov = fov;\n                    camera.updateProjectionMatrix();\n                };\n\n                // Reset View (Reset to Start Scene & forward orientation)\n                document.getElementById(\"btn-reset\").onclick = () => {\n                    lon = 0;\n                    lat = 0;\n                    velocityLon = 0;\n                    velocityLat = 0;\n                    fov = defaultFov;\n                    camera.fov = fov;\n                    camera.updateProjectionMatrix();\n\n                    notifyParent({ type: \"reset_to_start\" });\n                };\n\n                // Fullscreen\n                document.getElementById(\"btn-fullscreen\").onclick = () => {\n                    if (!document.fullscreenElement) {\n                        document.documentElement.requestFullscreen().catch(() => {});\n                    } else {\n                        document.exitFullscreen().catch(() => {});\n                    }\n                };\n\n                // Toggle Bottom Filmstrip Drawer\n                const toggleBtn = document.getElementById(\"toggle-filmstrip-btn\");\n                const filmstripBox = document.getElementById(\"filmstrip-container\");\n                const arrowSpan = document.getElementById(\"filmstrip-arrow\");\n                toggleBtn.onclick = () => {\n                    filmstripOpen = !filmstripOpen;\n                    const hotspotsDock = document.getElementById(\"hotspots-dock\");\n                    if (filmstripOpen) {\n                        filmstripBox.style.display = \"block\";\n                        arrowSpan.textContent = \"▾\";\n                        if (hotspotsDock) hotspotsDock.style.bottom = \"165px\";\n                    } else {\n                        filmstripBox.style.display = \"none\";\n                        arrowSpan.textContent = \"▴\";\n                        if (hotspotsDock) hotspotsDock.style.bottom = \"56px\";\n                    }\n                };\n            }\n\n            function setupControls() {\n                const canvas = document.getElementById(\"canvas\");\n\n                // Mouse Drag with Momentum Tracking\n                canvas.addEventListener(\"mousedown\", (e) => {\n                    isDragging = true;\n                    velocityLon = 0;\n                    velocityLat = 0;\n                    mouseMovedDistance = 0;\n                    previousMousePosition = { x: e.clientX, y: e.clientY };\n                });\n\n                window.addEventListener(\"mousemove\", (e) => {\n                    if (isDragging) {\n                        const deltaX = e.clientX - previousMousePosition.x;\n                        const deltaY = e.clientY - previousMousePosition.y;\n                        mouseMovedDistance += Math.abs(deltaX) + Math.abs(deltaY);\n\n                        velocityLon = -deltaX * 0.12;\n                        velocityLat = deltaY * 0.12;\n\n                        lon += velocityLon;\n                        lat += velocityLat;\n                        lat = Math.max(-85, Math.min(85, lat));\n                        previousMousePosition = { x: e.clientX, y: e.clientY };\n                    }\n\n                    // Hover Raycasting for Ground Chevron Glow & Pointer\n                    if (!isDragging && clickableHitboxes.length > 0) {\n                        const raycaster = new THREE.Raycaster();\n                        const mouse = new THREE.Vector2(\n                            (e.clientX / window.innerWidth) * 2 - 1,\n                            -(e.clientY / window.innerHeight) * 2 + 1,\n                        );\n                        raycaster.setFromCamera(mouse, camera);\n                        const intersects = raycaster.intersectObjects(clickableHitboxes);\n\n                        if (intersects.length > 0) {\n                            canvas.classList.add(\"pointer-cursor\");\n                            const hit = intersects[0].object;\n                            if (hoveredHitbox !== hit) {\n                                if (hoveredHitbox) setChevronHoverState(hoveredHitbox, false);\n                                hoveredHitbox = hit;\n                                setChevronHoverState(hoveredHitbox, true);\n                            }\n                        } else {\n                            canvas.classList.remove(\"pointer-cursor\");\n                            if (hoveredHitbox) {\n                                setChevronHoverState(hoveredHitbox, false);\n                                hoveredHitbox = null;\n                            }\n                        }\n                    }\n                });\n\n                window.addEventListener(\"mouseup\", () => {\n                    isDragging = false;\n                });\n\n                // Smooth Mouse Wheel Zoom\n                canvas.addEventListener(\"wheel\", (e) => {\n                    e.preventDefault();\n                    fov += e.deltaY * 0.05;\n                    fov = Math.max(minFov, Math.min(maxFov, fov));\n                    camera.fov = fov;\n                    camera.updateProjectionMatrix();\n                }, { passive: false });\n\n                // Touch Drag & Pinch Zoom\n                let initialPinchDistance = 0;\n                canvas.addEventListener(\"touchstart\", (e) => {\n                    if (e.touches.length === 2) {\n                        const dx = e.touches[0].clientX - e.touches[1].clientX;\n                        const dy = e.touches[0].clientY - e.touches[1].clientY;\n                        initialPinchDistance = Math.sqrt(dx * dx + dy * dy);\n                    } else if (e.touches.length === 1) {\n                        isDragging = true;\n                        velocityLon = 0;\n                        velocityLat = 0;\n                        mouseMovedDistance = 0;\n                        previousMousePosition = {\n                            x: e.touches[0].clientX,\n                            y: e.touches[0].clientY,\n                        };\n                    }\n                });\n\n                canvas.addEventListener(\"touchmove\", (e) => {\n                    if (e.touches.length === 2) {\n                        const dx = e.touches[0].clientX - e.touches[1].clientX;\n                        const dy = e.touches[0].clientY - e.touches[1].clientY;\n                        const distance = Math.sqrt(dx * dx + dy * dy);\n                        const delta = distance - initialPinchDistance;\n                        fov -= delta * 0.1;\n                        fov = Math.max(minFov, Math.min(maxFov, fov));\n                        camera.fov = fov;\n                        camera.updateProjectionMatrix();\n                        initialPinchDistance = distance;\n                    } else if (isDragging && e.touches.length === 1) {\n                        const deltaX = e.touches[0].clientX - previousMousePosition.x;\n                        const deltaY = e.touches[0].clientY - previousMousePosition.y;\n                        mouseMovedDistance += Math.abs(deltaX) + Math.abs(deltaY);\n\n                        velocityLon = -deltaX * 0.12;\n                        velocityLat = deltaY * 0.12;\n\n                        lon += velocityLon;\n                        lat += velocityLat;\n                        lat = Math.max(-85, Math.min(85, lat));\n                        previousMousePosition = {\n                            x: e.touches[0].clientX,\n                            y: e.touches[0].clientY,\n                        };\n                    }\n                });\n\n                canvas.addEventListener(\"touchend\", (e) => {\n                    isDragging = false;\n                    if (mouseMovedDistance <= 12 && !isTransitioning && previousMousePosition) {\n                        const raycaster = new THREE.Raycaster();\n                        const mouse = new THREE.Vector2(\n                            (previousMousePosition.x / window.innerWidth) * 2 - 1,\n                            -(previousMousePosition.y / window.innerHeight) * 2 + 1,\n                        );\n                        raycaster.setFromCamera(mouse, camera);\n                        const intersects = raycaster.intersectObjects(clickableHitboxes);\n                        if (intersects.length > 0) {\n                            const hotspot = intersects[0].object.userData.hotspot;\n                            triggerGoogleStreetViewStep(hotspot, intersects[0].point);\n                        }\n                    }\n                });\n\n                // Single Click on Floor Chevron\n                canvas.addEventListener(\"click\", (e) => {\n                    if (mouseMovedDistance > 10 || isTransitioning) return;\n\n                    const raycaster = new THREE.Raycaster();\n                    const mouse = new THREE.Vector2(\n                        (e.clientX / window.innerWidth) * 2 - 1,\n                        -(e.clientY / window.innerHeight) * 2 + 1,\n                    );\n                    raycaster.setFromCamera(mouse, camera);\n                    const intersects = raycaster.intersectObjects(clickableHitboxes);\n                    if (intersects.length > 0) {\n                        const hotspot = intersects[0].object.userData.hotspot;\n                        triggerGoogleStreetViewStep(hotspot, intersects[0].point);\n                    }\n                });\n\n                // Double Click anywhere on ground to step towards that doorway\n                canvas.addEventListener(\"dblclick\", (e) => {\n                    if (isTransitioning || clickableHitboxes.length === 0) return;\n\n                    const raycaster = new THREE.Raycaster();\n                    const mouse = new THREE.Vector2(\n                        (e.clientX / window.innerWidth) * 2 - 1,\n                        -(e.clientY / window.innerHeight) * 2 + 1,\n                    );\n                    raycaster.setFromCamera(mouse, camera);\n                    const intersects = raycaster.intersectObjects(clickableHitboxes);\n                    if (intersects.length > 0) {\n                        const hotspot = intersects[0].object.userData.hotspot;\n                        triggerGoogleStreetViewStep(hotspot, intersects[0].point);\n                        return;\n                    }\n\n                    // Otherwise find closest hotspot in view direction\n                    const camDir = new THREE.Vector3();\n                    camera.getWorldDirection(camDir);\n\n                    let closestHotspot = null;\n                    let closestAngle = Infinity;\n\n                    clickableHitboxes.forEach((mesh) => {\n                        const hsDir = mesh.position.clone().normalize();\n                        const angle = camDir.angleTo(hsDir);\n                        if (angle < closestAngle && angle < 0.8) {\n                            closestAngle = angle;\n                            closestHotspot = mesh.userData.hotspot;\n                        }\n                    });\n\n                    if (closestHotspot) {\n                        triggerGoogleStreetViewStep(closestHotspot);\n                    }\n                });\n            }\n\n            function setChevronHoverState(hitboxMesh, isHovered) {\n                const group = hitboxMesh.userData.parentGroup;\n                const label = document.getElementById(hitboxMesh.userData.labelId);\n                const chevron = hitboxMesh.userData.chevronMesh;\n\n                if (isHovered) {\n                    if (chevron) chevron.scale.set(1.12, 1.12, 1.12);\n                    if (label) {\n                        label.style.opacity = \"1\";\n                        label.style.transform = \"translate(-50%, -100%) scale(1.05)\";\n                    }\n                } else {\n                    if (chevron) chevron.scale.set(1.0, 1.0, 1.0);\n                    if (label) {\n                        label.style.opacity = \"0\";\n                        label.style.transform = \"translate(-50%, -100%) scale(1.0)\";\n                    }\n                }\n            }\n\n            // Google Street View Forward Dolly & Crossfade Walkthrough Animation\n            function triggerGoogleStreetViewStep(hotspot, clickPoint) {\n                if (isTransitioning) return;\n                isTransitioning = true;\n\n                if (clickPoint) {\n                    spawnClickRipple(clickPoint);\n                }\n\n                const rawTargetId = hotspot.target_scene_id || hotspot.target_scene;\n                const targetSceneId = (typeof rawTargetId === \"object\" && rawTargetId) ? rawTargetId.id : rawTargetId;\n                if (!targetSceneId) {\n                    console.warn(\"Hotspot has no target scene:\", hotspot);\n                    isTransitioning = false;\n                    return;\n                }\n\n                const startFov = camera.fov;\n                const targetFov = 38; // Dolly zoom forward into room\n                const duration = 280;\n                const startTime = performance.now();\n\n                const crossfade = document.getElementById(\"crossfade-overlay\");\n                if (crossfade) crossfade.style.opacity = \"0.45\";\n\n                function animateStep(currentTime) {\n                    const elapsed = currentTime - startTime;\n                    const progress = Math.min(elapsed / duration, 1.0);\n                    const ease = progress * (2 - progress); // smooth quadratic ease-out\n\n                    camera.fov = startFov + (targetFov - startFov) * ease;\n                    camera.updateProjectionMatrix();\n\n                    if (progress < 1.0) {\n                        requestAnimationFrame(animateStep);\n                    } else {\n                        notifyParent({\n                            type: \"hotspot_clicked\",\n                            target_scene_id: targetSceneId,\n                            label: hotspot.label,\n                        });\n\n                        setTimeout(() => {\n                            if (crossfade) crossfade.style.opacity = \"0\";\n                            camera.fov = defaultFov;\n                            camera.updateProjectionMatrix();\n                            isTransitioning = false;\n                        }, 200);\n                    }\n                }\n                requestAnimationFrame(animateStep);\n            }\n\n            function spawnClickRipple(point) {\n                const geom = new THREE.RingGeometry(2, 8, 32);\n                const mat = new THREE.MeshBasicMaterial({\n                    color: 0xffffff,\n                    transparent: true,\n                    opacity: 0.85,\n                    side: THREE.DoubleSide,\n                });\n                const ripple = new THREE.Mesh(geom, mat);\n                ripple.position.copy(point);\n                ripple.lookAt(camera.position);\n                scene.add(ripple);\n\n                rippleMeshes.push({\n                    mesh: ripple,\n                    startTime: performance.now(),\n                    duration: 380,\n                });\n            }\n\n            function createGoogleStreetViewHotspots() {\n                cleanupHotspots();\n                currentHotspots.forEach((hotspot) => {\n                    const yaw = hotspot.yaw || 0;\n                    const pitch = (hotspot.pitch !== undefined && hotspot.pitch !== 0) ? hotspot.pitch : -18;\n                    const phi = THREE.MathUtils.degToRad(90 - pitch);\n                    const theta = THREE.MathUtils.degToRad(yaw - 90);\n\n                    const distance = 280;\n                    const x = distance * Math.sin(phi) * Math.cos(theta);\n                    const y = distance * Math.cos(phi);\n                    const z = distance * Math.sin(phi) * Math.sin(theta);\n\n                    const group = new THREE.Group();\n                    group.position.set(x, y, z);\n                    group.lookAt(0, y, 0); // Always point group directly towards camera/origin so -Z points forward\n                    group.userData = { originalY: y, yaw: yaw };\n\n                    // 1. Google Street View Floor Chevron Disc\n                    const discGeom = new THREE.PlaneGeometry(62, 62);\n                    const discMat = new THREE.MeshBasicMaterial({\n                        map: chevronTexture,\n                        transparent: true,\n                        side: THREE.DoubleSide,\n                        depthWrite: false,\n                    });\n                    const chevronMesh = new THREE.Mesh(discGeom, discMat);\n                    chevronMesh.rotation.x = -Math.PI / 2.3;\n                    group.add(chevronMesh);\n\n                    // 2. Subtle Ground Outer Ring\n                    const groundRingGeom = new THREE.RingGeometry(34, 37, 32);\n                    const groundRingMat = new THREE.MeshBasicMaterial({\n                        color: 0xffffff,\n                        transparent: true,\n                        opacity: 0.45,\n                        side: THREE.DoubleSide,\n                        depthWrite: false,\n                    });\n                    const groundRing = new THREE.Mesh(groundRingGeom, groundRingMat);\n                    groundRing.rotation.x = -Math.PI / 2.3;\n                    group.add(groundRing);\n\n                    // 3. Invisible Raycast Hitbox Sphere\n                    const hitBoxGeom = new THREE.SphereGeometry(36, 16, 16);\n                    const hitBoxMat = new THREE.MeshBasicMaterial({ visible: false });\n                    const hitBox = new THREE.Mesh(hitBoxGeom, hitBoxMat);\n                    hitBox.userData = {\n                        hotspot: hotspot,\n                        parentGroup: group,\n                        chevronMesh: chevronMesh,\n                        groundRing: groundRing,\n                        labelId: \"label-\" + clickableHitboxes.length,\n                    };\n                    group.add(hitBox);\n\n                    scene.add(group);\n                    hotspotGroups.push(group);\n                    clickableHitboxes.push(hitBox);\n\n                    // 4. Floating Destination Label Badge\n                    const labelContainer = document.getElementById(\"floating-labels\");\n                    const labelDiv = document.createElement(\"div\");\n                    labelDiv.className = \"floating-label\";\n                    labelDiv.id = hitBox.userData.labelId;\n                    labelDiv.innerHTML = `<span class=\"arrow-icon\">➔</span> <span>${hotspot.label || hotspot.target_scene_title || \"Walk Forward\"}</span>`;\n                    labelContainer.appendChild(labelDiv);\n                });\n            }\n\n            function renderFilmstrip() {\n                const container = document.getElementById(\"filmstrip-cards\");\n                if (!container) return;\n                container.innerHTML = \"\";\n\n                allScenesList.forEach((sceneItem) => {\n                    const card = document.createElement(\"div\");\n                    card.className = \"filmstrip-card\" + (sceneItem.title === currentSceneTitle ? \" active\" : \"\");\n                    card.innerHTML = `\n                        <img src=\"${sceneItem.image_url}\" alt=\"${sceneItem.title}\" onerror=\"this.style.display='none'\" />\n                        <div class=\"filmstrip-card-title\">${sceneItem.title}</div>\n                    `;\n                    card.onclick = () => {\n                        triggerGoogleStreetViewStep({ target_scene_id: sceneItem.id, label: sceneItem.title });\n                    };\n                    container.appendChild(card);\n                });\n            }\n\n            function animate() {\n                animFrameId = requestAnimationFrame(animate);\n\n                // Inertia & Friction Momentum Damping\n                if (!isDragging) {\n                    lon += velocityLon;\n                    lat += velocityLat;\n                    velocityLon *= 0.88;\n                    velocityLat *= 0.88;\n                    if (Math.abs(velocityLon) < 0.001) velocityLon = 0;\n                    if (Math.abs(velocityLat) < 0.001) velocityLat = 0;\n                }\n                lat = Math.max(-85, Math.min(85, lat));\n\n                // Camera Look Target\n                const phi = THREE.MathUtils.degToRad(90 - lat);\n                const theta = THREE.MathUtils.degToRad(lon - 90);\n                const cameraTarget = new THREE.Vector3(\n                    500 * Math.sin(phi) * Math.cos(theta),\n                    500 * Math.cos(phi),\n                    500 * Math.sin(phi) * Math.sin(theta)\n                );\n                camera.lookAt(cameraTarget);\n\n                // Update Compass Needle Orientation\n                const compassNeedle = document.getElementById(\"compass-needle\");\n                if (compassNeedle) {\n                    compassNeedle.style.transform = `rotate(${-lon}deg)`;\n                }\n\n                const time = Date.now() * 0.004;\n\n                // Animate chevron arrows and floating badges\n                clickableHitboxes.forEach((mesh, index) => {\n                    const group = mesh.userData.parentGroup;\n                    const ring = mesh.userData.groundRing;\n\n                    // Subtle breathing pulse\n                    const pulse = 1.0 + Math.abs(Math.sin(time * 2.5 + index)) * 0.18;\n                    if (ring) {\n                        ring.scale.set(pulse, pulse, pulse);\n                        ring.material.opacity = 0.5 - (pulse - 1.0) * 1.5;\n                    }\n\n                    // 3D to 2D screen projection for floating label badge\n                    const pos = group.position.clone();\n                    pos.y += 24.0;\n                    pos.project(camera);\n\n                    const label = document.getElementById(mesh.userData.labelId);\n                    if (label) {\n                        if (pos.z > 1 || pos.x < -1.1 || pos.x > 1.1 || pos.y < -1.1 || pos.y > 1.1) {\n                            label.style.display = \"none\";\n                        } else {\n                            label.style.display = \"flex\";\n                            const x = (pos.x * 0.5 + 0.5) * window.innerWidth;\n                            const y = (pos.y * -0.5 + 0.5) * window.innerHeight;\n                            label.style.left = x + \"px\";\n                            label.style.top = y + \"px\";\n                        }\n                    }\n                });\n\n                // Animate click ripples\n                const now = performance.now();\n                for (let i = rippleMeshes.length - 1; i >= 0; i--) {\n                    const r = rippleMeshes[i];\n                    const elapsed = now - r.startTime;\n                    const prog = elapsed / r.duration;\n                    if (prog >= 1.0) {\n                        scene.remove(r.mesh);\n                        r.mesh.geometry.dispose();\n                        r.mesh.material.dispose();\n                        rippleMeshes.splice(i, 1);\n                    } else {\n                        const scale = 1.0 + prog * 4.0;\n                        r.mesh.scale.set(scale, scale, scale);\n                        r.mesh.material.opacity = 0.85 * (1.0 - prog);\n                    }\n                }\n\n                renderer.render(scene, camera);\n            }\n\n            function notifyParent(data) {\n                if (window.ReactNativeWebView) {\n                    try { window.ReactNativeWebView.postMessage(JSON.stringify(data)); } catch (e) {}\n                }\n                if (window.parent && window.parent !== window) {\n                    window.parent.postMessage(data, \"*\");\n                }\n            }\n\n            function handleIncomingMsg(event) {\n                try {\n                    const data = typeof event.data === \"string\" ? JSON.parse(event.data) : event.data;\n                    if (data && data.type === \"init\") {\n                        init(data.imageUrl, data.hotspots, data.title, data.buildingName, data.allScenes);\n                    }\n                } catch (e) {\n                    console.error(\"Message parse error:\", e);\n                }\n            }\n            window.addEventListener(\"message\", handleIncomingMsg);\n            document.addEventListener(\"message\", handleIncomingMsg);\n            if (false) window.addEventListener(\"message\", (event) => {\n                try {\n                    const data = typeof event.data === \"string\" ? JSON.parse(event.data) : event.data;\n                    if (data && data.type === \"init\") {\n                        init(data.imageUrl, data.hotspots, data.title, data.buildingName, data.allScenes);\n                    }\n                } catch (e) {\n                    console.error(\"Message parse error:\", e);\n                }\n            });\n        </script>\n    </body>\n</html>\n";
